// A port of the parts of moment.js 2.30.1 Obsidian relies on (format(), strict parsing, "en" locale data).
// The structure deliberately follows moment's own algorithms (token regexes, expandFormat, week maths,
// configFromArray/checkOverflow) so that edge cases behave identically; see the golden vectors in
// tests/fixtures/moment/vectors.json (generated by tests/fixtures/moment/gen_vectors.js).

namespace oc {
namespace {

// ---------------------------------------------------------------------------------------------------------
// Calendar arithmetic: proleptic Gregorian with astronomical years (0 = 1 BC), like JS Dates.

qint64 floorDiv(qint64 a, qint64 b)
{
    qint64 q = a / b;
    if ((a % b != 0) && ((a < 0) != (b < 0)))
        --q;
    return q;
}

qint64 floorMod(qint64 a, qint64 b) { return a - floorDiv(a, b) * b; }

bool isLeapYear(qint64 y) { return (y % 4 == 0 && y % 100 != 0) || y % 400 == 0; }

int daysInYear(qint64 y) { return isLeapYear(y) ? 366 : 365; }

// moment's daysInMonth(year, month0); out-of-range months wrap into adjacent years.
int daysInMonth(qint64 year, qint64 month0)
{
    const qint64 m = floorMod(month0, 12);
    year += (month0 - m) / 12;
    return m == 1 ? (isLeapYear(year) ? 29 : 28) : int(31 - ((m % 7) % 2));
}

// Days since 1970-01-01 (H. Hinnant's algorithm). `d` may exceed the month length (it simply adds days).
qint64 daysFromCivil(qint64 y, int m, qint64 d)
{
    y -= m <= 2 ? 1 : 0;
    const qint64 era = floorDiv(y, 400);
    const qint64 yoe = y - era * 400;
    const qint64 doy = (153 * (m + (m > 2 ? -3 : 9)) + 2) / 5 + d - 1;
    const qint64 doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    return era * 146097 + doe - 719468;
}

struct Civil {
    qint64 y = 1970;
    int m = 1;
    int d = 1;
};

Civil civilFromDays(qint64 z)
{
    z += 719468;
    const qint64 era = floorDiv(z, 146097);
    const qint64 doe = z - era * 146097;
    const qint64 yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    const qint64 doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    const qint64 mp = (5 * doy + 2) / 153;
    Civil c;
    c.d = int(doy - (153 * mp + 2) / 5 + 1);
    c.m = int(mp < 10 ? mp + 3 : mp - 9);
    c.y = yoe + era * 400 + (c.m <= 2 ? 1 : 0);
    return c;
}

int weekdayOfDays(qint64 days) { return int(floorMod(days + 4, 7)); } // 0 = Sunday (1970-01-01 was a Thursday)

int dayOfYear(qint64 y, int m, int d) { return int(daysFromCivil(y, m, d) - daysFromCivil(y, 1, 1)) + 1; }

// start-of-first-week minus start-of-year (moment's firstWeekOffset).
int firstWeekOffset(qint64 year, int dow, int doy)
{
    const int fwd = 7 + dow - doy; // the January day that is always in the first week
    const int fwdlw = (7 + weekdayOfDays(daysFromCivil(year, 1, fwd)) - dow) % 7;
    return -fwdlw + fwd - 1;
}

int weeksInYear(qint64 year, int dow, int doy)
{
    return (daysInYear(year) - firstWeekOffset(year, dow, doy) + firstWeekOffset(year + 1, dow, doy)) / 7;
}

struct WeekOfYear {
    int week = 1;
    qint64 year = 1970;
};

WeekOfYear weekOfYear(qint64 year, int dayOfYearValue, int dow, int doy)
{
    const int week = int(floorDiv(dayOfYearValue - firstWeekOffset(year, dow, doy) - 1, 7)) + 1;
    if (week < 1)
        return {week + weeksInYear(year - 1, dow, doy), year - 1};
    const int wiy = weeksInYear(year, dow, doy);
    if (week > wiy)
        return {week - wiy, year + 1};
    return {week, year};
}

struct YearDayOfYear {
    qint64 year = 1970;
    qint64 dayOfYear = 1;
};

YearDayOfYear dayOfYearFromWeeks(qint64 year, qint64 week, qint64 weekday, int dow, int doy)
{
    const qint64 localWeekday = (7 + weekday - dow) % 7;
    const qint64 day = 1 + 7 * (week - 1) + localWeekday + firstWeekOffset(year, dow, doy);
    if (day <= 0)
        return {year - 1, daysInYear(year - 1) + day};
    if (day > daysInYear(year))
        return {year + 1, day - daysInYear(year)};
    return {year, day};
}

// JS Date range: +-8.64e15 ms around the epoch.
constexpr qint64 kMaxEpochMs = 8'640'000'000'000'000;
bool yearInDateRange(qint64 y) { return y >= -271820 && y <= 275759; }

qint64 toAstronomicalYear(int qdateYear) { return qdateYear < 0 ? qdateYear + 1 : qdateYear; }
int toQDateYear(qint64 astronomicalYear) { return int(astronomicalYear <= 0 ? astronomicalYear - 1 : astronomicalYear); }

// ---------------------------------------------------------------------------------------------------------
// Tokenizer (moment's formattingTokens / localFormattingTokens regexes, hand-written for exactness).

bool isLineTerminator(QChar c) { return c == u'\n' || c == u'\r' || c == QChar(0x2028) || c == QChar(0x2029); }

// `\[[^\[]*\]` at p: the group ends at the LAST ']' before the next '[' (greedy + backtracking).
qsizetype bracketGroupEnd(QStringView s, qsizetype p)
{
    qsizetype last = -1;
    for (qsizetype q = p + 1; q < s.size() && s[q] != u'['; ++q)
        if (s[q] == u']')
            last = q;
    return last;
}

qsizetype runOf(QStringView s, qsizetype p, QChar c, qsizetype max)
{
    qsizetype n = 0;
    while (p + n < s.size() && n < max && s[p + n] == c)
        ++n;
    return n;
}

// Length of the token matched by moment's big alternation at p (0 when nothing matches, i.e. a line break).
qsizetype bigTokenLength(QStringView s, qsizetype p)
{
    const auto at = [&](qsizetype i) { return i < s.size() ? s[i] : QChar(); };
    const QChar c = s[p];
    switch (c.unicode()) {
    case u'H':
    case u'h':
        if (at(p + 1) == u'm' && at(p + 2) == u'm') // [Hh]mm(ss)?
            return at(p + 3) == u's' && at(p + 4) == u's' ? 5 : 3;
        return at(p + 1) == c ? 2 : 1; // hh? HH?
    case u'M':
        return at(p + 1) == u'o' ? 2 : runOf(s, p, u'M', 4); // Mo | MM?M?M?
    case u'D':
        if (at(p + 1) == u'o')
            return 2; // Do
        if (at(p + 1) == u'D' && at(p + 2) == u'D' && at(p + 3) == u'o')
            return 4; // DDDo
        return runOf(s, p, u'D', 4);
    case u'd':
        if (at(p + 1) == u'd')
            return runOf(s, p, u'd', 4); // ddd?d?
        return at(p + 1) == u'o' ? 2 : 1; // do?
    case u'w':
    case u'W': { // w[o|w]?  W[o|W]?  (the class really contains '|')
        const QChar n = at(p + 1);
        return (n == u'o' || n == u'|' || n == c) ? 2 : 1;
    }
    case u'Q':
        return at(p + 1) == u'o' ? 2 : 1;
    case u'N':
        return runOf(s, p, u'N', 5);
    case u'Y': {
        const qsizetype r = runOf(s, p, u'Y', 6);
        return r >= 4 ? r : (r >= 2 ? 2 : 1); // YYYYYY|YYYYY|YYYY|YY, a single Y via '.'
    }
    case u'y': {
        const qsizetype r = runOf(s, p, u'y', 4);
        if (r >= 2)
            return r; // y{2,4}
        return at(p + 1) == u'o' ? 2 : 1; // yo?
    }
    case u'g':
    case u'G': {
        const qsizetype r = runOf(s, p, c, 5); // gg(ggg?)?
        return r >= 4 ? r : (r >= 2 ? 2 : 1);
    }
    case u'k':
    case u'm':
    case u's':
    case u'z':
    case u'Z':
        return at(p + 1) == c ? 2 : 1;
    case u'S':
        return runOf(s, p, u'S', 9);
    default:
        return isLineTerminator(c) ? 0 : 1; // '.'
    }
}

QStringList tokenize(QStringView s)
{
    QStringList out;
    qsizetype p = 0;
    while (p < s.size()) {
        if (s[p] == u'[') {
            const qsizetype end = bracketGroupEnd(s, p);
            if (end >= 0) {
                out.push_back(s.mid(p, end - p + 1).toString());
                p = end + 1;
                continue;
            }
        }
        if (s[p] == u'\\' && p + 1 < s.size()) {
            const qsizetype len = bigTokenLength(s, p + 1);
            if (len > 0) {
                out.push_back(s.mid(p, len + 1).toString());
                p += len + 1;
                continue;
            }
        }
        const qsizetype len = bigTokenLength(s, p);
        if (len > 0) {
            out.push_back(s.mid(p, len).toString());
            p += len;
        } else {
            ++p; // line terminators never match: dropped
        }
    }
    return out;
}

// LTS|LT|LL?L?L?|l{1,4}
qsizetype localTokenLength(QStringView s, qsizetype p)
{
    if (p >= s.size())
        return 0;
    if (s.mid(p).startsWith(u"LTS"))
        return 3;
    if (s.mid(p).startsWith(u"LT"))
        return 2;
    if (s[p] == u'L')
        return runOf(s, p, u'L', 4);
    if (s[p] == u'l')
        return runOf(s, p, u'l', 4);
    return 0;
}

// moment's removeFormattingTokens(): literal output of a non-token.
QString removeFormattingTokens(const QString& tok)
{
    const qsizetype b = tok.indexOf(u'[');
    if (b >= 0 && b + 1 < tok.size()) { // /\[[\s\S]/
        QString t = tok;
        if (t.startsWith(u'['))
            t.remove(0, 1);
        if (t.endsWith(u']'))
            t.chop(1);
        return t;
    }
    QString t = tok;
    t.remove(u'\\');
    return t;
}

// moment's unescapeFormat(): the literal a non-token must match when parsing.
QString unescapeFormat(const QString& tok)
{
    QString s = tok;
    const qsizetype bs = s.indexOf(u'\\');
    if (bs >= 0)
        s.remove(bs, 1); // .replace('\\', '') replaces the first backslash only
    QString out;
    qsizetype p = 0;
    while (p < s.size()) {
        const QChar c = s[p];
        if (c == u'\\' && p + 1 < s.size()) {
            const QChar n = s[p + 1];
            if (n == u'[' || n == u']' || !isLineTerminator(n)) { // \\(\[) | \\(\]) | \\(.)
                out += n;
                p += 2;
                continue;
            }
        }
        if (c == u'[') { // \[([^\]\[]*)\]
            qsizetype q = p + 1;
            while (q < s.size() && s[q] != u']' && s[q] != u'[')
                ++q;
            if (q < s.size() && s[q] == u']') {
                const QString inner = s.mid(p + 1, q - p - 1);
                out += inner.isEmpty() ? QStringLiteral("undefined") : inner; // p1||p2||p3||p4 with p3 === ''
                p = q + 1;
                continue;
            }
        }
        out += c;
        ++p;
    }
    return out;
}

// ---------------------------------------------------------------------------------------------------------
// Token ids

enum Tok : int {
    kY, kYY, kYYYY, kYYYYY, kYYYYYY, kQ, kQo, kM, kMo, kMM, kMMM, kMMMM, kD, kDo, kDD, kDDD, kDDDo, kDDDD,
    kd, kdo, kdd, kddd, kdddd, ke, kE, kw, kwo, kww, kW, kWo, kWW, kgg, kgggg, kggggg, kGG, kGGGG, kGGGGG,
    kH, kHH, kh, khh, kk, kkk, khmm, khmmss, kHmm, kHmmss, km, kmm, ks, kss,
    kS1, kS2, kS3, kS4, kS5, kS6, kS7, kS8, kS9,
    ka, kA, kZ, kZZ, kX, kx, kz, kzz, kN, kNNNN, kNNNNN, ky, kyo, kyy, kyyy, kyyyy,
};

const QHash<QString, int>& tokenIds()
{
    static const QHash<QString, int> ids = [] {
        QHash<QString, int> h;
        const std::initializer_list<std::pair<const char*, int>> list = {
            {"Y", kY}, {"YY", kYY}, {"YYYY", kYYYY}, {"YYYYY", kYYYYY}, {"YYYYYY", kYYYYYY}, {"Q", kQ}, {"Qo", kQo},
            {"M", kM}, {"Mo", kMo}, {"MM", kMM}, {"MMM", kMMM}, {"MMMM", kMMMM}, {"D", kD}, {"Do", kDo}, {"DD", kDD},
            {"DDD", kDDD}, {"DDDo", kDDDo}, {"DDDD", kDDDD}, {"d", kd}, {"do", kdo}, {"dd", kdd}, {"ddd", kddd},
            {"dddd", kdddd}, {"e", ke}, {"E", kE}, {"w", kw}, {"wo", kwo}, {"ww", kww}, {"W", kW}, {"Wo", kWo},
            {"WW", kWW}, {"gg", kgg}, {"gggg", kgggg}, {"ggggg", kggggg}, {"GG", kGG}, {"GGGG", kGGGG},
            {"GGGGG", kGGGGG}, {"H", kH}, {"HH", kHH}, {"h", kh}, {"hh", khh}, {"k", kk}, {"kk", kkk},
            {"hmm", khmm}, {"hmmss", khmmss}, {"Hmm", kHmm}, {"Hmmss", kHmmss}, {"m", km}, {"mm", kmm}, {"s", ks},
            {"ss", kss}, {"S", kS1}, {"SS", kS2}, {"SSS", kS3}, {"SSSS", kS4}, {"SSSSS", kS5}, {"SSSSSS", kS6},
            {"SSSSSSS", kS7}, {"SSSSSSSS", kS8}, {"SSSSSSSSS", kS9}, {"a", ka}, {"A", kA}, {"Z", kZ}, {"ZZ", kZZ},
            {"X", kX}, {"x", kx}, {"z", kz}, {"zz", kzz}, {"N", kN}, {"NN", kN}, {"NNN", kN}, {"NNNN", kNNNN},
            {"NNNNN", kNNNNN}, {"y", ky}, {"yo", kyo}, {"yy", kyy}, {"yyy", kyyy}, {"yyyy", kyyyy},
        };
        for (const auto& [k, v] : list)
            h.insert(QString::fromLatin1(k), v);
        return h;
    }();
    return ids;
}

int tokenId(const QString& tok) { return tokenIds().value(tok, -1); }

// ---------------------------------------------------------------------------------------------------------
// Locale data

struct LocaleData {
    bool english = true;
    std::array<QString, 12> months, monthsStandalone, monthsShort, monthsShortStandalone;
    std::array<QString, 7> weekdays, weekdaysShort, weekdaysMin; // index 0 = Sunday
    int dow = 0;                                                 // first day of week (0 = Sunday)
    int doy = 6;                                                 // 7 + dow - (Jan day always in week 1)
    QString am = QStringLiteral("AM"), pm = QStringLiteral("PM");
    QHash<QString, QString> longFormats; // LT LTS L LL LLL LLLL l ll lll llll
};

// moment derives l/ll/lll/llll from the uppercase formats by shortening MMMM, MM, DD and dddd.
QString lowercaseLongFormat(const QString& upper)
{
    QString out;
    for (const QString& tok : tokenize(upper)) {
        const bool shorten = tok == QLatin1StringView("MMMM") || tok == QLatin1StringView("MM") || tok == QLatin1StringView("DD")
            || tok == QLatin1StringView("dddd");
        out += shorten ? tok.mid(1) : tok;
    }
    return out;
}

void deriveLowercaseFormats(LocaleData& d)
{
    for (const char* key : {"L", "LL", "LLL", "LLLL"}) {
        const QString k = QString::fromLatin1(key);
        d.longFormats.insert(k.toLower(), lowercaseLongFormat(d.longFormats.value(k)));
    }
}

std::shared_ptr<const LocaleData> makeEnglish()
{
    auto d = std::make_shared<LocaleData>();
    const char* months[] = {"January", "February", "March", "April", "May", "June", "July", "August", "September",
                            "October", "November", "December"};
    const char* weekdays[] = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};
    for (int i = 0; i < 12; ++i) {
        d->months[i] = d->monthsStandalone[i] = QString::fromLatin1(months[i]);
        d->monthsShort[i] = d->monthsShortStandalone[i] = d->months[i].left(3);
    }
    for (int i = 0; i < 7; ++i) {
        d->weekdays[i] = QString::fromLatin1(weekdays[i]);
        d->weekdaysShort[i] = d->weekdays[i].left(3);
        d->weekdaysMin[i] = d->weekdays[i].left(2);
    }
    d->longFormats = {{QStringLiteral("LTS"), QStringLiteral("h:mm:ss A")},
                      {QStringLiteral("LT"), QStringLiteral("h:mm A")},
                      {QStringLiteral("L"), QStringLiteral("MM/DD/YYYY")},
                      {QStringLiteral("LL"), QStringLiteral("MMMM D, YYYY")},
                      {QStringLiteral("LLL"), QStringLiteral("MMMM D, YYYY h:mm A")},
                      {QStringLiteral("LLLL"), QStringLiteral("dddd, MMMM D, YYYY h:mm A")}};
    deriveLowercaseFormats(*d);
    return d;
}

// Qt date/time format -> moment format (best effort, for non-English locales).
QString qtFormatToMoment(const QString& qt)
{
    const bool twelveHour = qt.contains(QLatin1StringView("AP"), Qt::CaseInsensitive) || qt.contains(u'a') || qt.contains(u'A');
    QString out;
    qsizetype i = 0;
    while (i < qt.size()) {
        const QChar c = qt[i];
        if (c == u'\'') { // quoted literal ('' is a quote)
            qsizetype j = i + 1;
            QString lit;
            while (j < qt.size()) {
                if (qt[j] == u'\'') {
                    if (j + 1 < qt.size() && qt[j + 1] == u'\'') {
                        lit += u'\'';
                        j += 2;
                        continue;
                    }
                    break;
                }
                lit += qt[j++];
            }
            if (!lit.isEmpty())
                out += u'[' + lit + u']';
            else if (j == i + 1)
                out += u'\'';
            i = j + 1;
            continue;
        }
        const qsizetype n = runOf(qt, i, c, 4);
        switch (c.unicode()) {
        case u'd':
            out += n == 1 ? QStringLiteral("D") : n == 2 ? QStringLiteral("DD") : n == 3 ? QStringLiteral("ddd") : QStringLiteral("dddd");
            break;
        case u'M':
            out += QString(n, u'M');
            break;
        case u'y':
            out += n >= 4 ? QStringLiteral("YYYY") : QStringLiteral("YY");
            break;
        case u'h':
            out += QString(n > 1 ? 2 : 1, twelveHour ? u'h' : u'H');
            break;
        case u'H':
            out += QString(n > 1 ? 2 : 1, u'H');
            break;
        case u'm':
        case u's':
            out += QString(n > 1 ? 2 : 1, c);
            break;
        case u'z':
            out += QStringLiteral("SSS");
            break;
        case u'A':
        case u'a':
            out += c == u'A' ? u'A' : u'a';
            if (i + 1 < qt.size() && (qt[i + 1] == u'P' || qt[i + 1] == u'p'))
                ++i; // AP / ap
            i += 1;
            continue;
        case u't':
            break; // time zone names are not representable
        default:
            if (c.isLetter())
                out += u'[' + QString(n, c) + u']';
            else
                out += QString(n, c);
            break;
        }
        i += n;
    }
    return out.trimmed();
}

std::shared_ptr<const LocaleData> makeFromQLocale(const QLocale& loc)
{
    auto d = std::make_shared<LocaleData>();
    d->english = false;
    for (int i = 0; i < 12; ++i) {
        d->months[i] = loc.monthName(i + 1, QLocale::LongFormat);
        d->monthsStandalone[i] = loc.standaloneMonthName(i + 1, QLocale::LongFormat);
        d->monthsShort[i] = loc.monthName(i + 1, QLocale::ShortFormat);
        d->monthsShortStandalone[i] = loc.standaloneMonthName(i + 1, QLocale::ShortFormat);
    }
    for (int i = 0; i < 7; ++i) {
        const int qtDay = i == 0 ? 7 : i;
        d->weekdays[i] = loc.dayName(qtDay, QLocale::LongFormat);
        d->weekdaysShort[i] = loc.dayName(qtDay, QLocale::ShortFormat);
        d->weekdaysMin[i] = d->weekdaysShort[i].left(2);
    }
    d->dow = int(loc.firstDayOfWeek()) % 7;
    d->doy = d->dow == 1 ? 4 : d->dow == 0 ? 6 : d->dow == 6 ? 12 : 6 + d->dow;
    if (!loc.amText().isEmpty())
        d->am = loc.amText();
    if (!loc.pmText().isEmpty())
        d->pm = loc.pmText();
    const QString lt = qtFormatToMoment(loc.timeFormat(QLocale::ShortFormat));
    QString lts = qtFormatToMoment(loc.timeFormat(QLocale::LongFormat));
    const QString date = qtFormatToMoment(loc.dateFormat(QLocale::ShortFormat)).replace(QStringLiteral("YYYY"), QStringLiteral("YY")).replace(QStringLiteral("YY"), QStringLiteral("YYYY"));
    const QString longDate = qtFormatToMoment(loc.dateFormat(QLocale::LongFormat));
    QString noWeekday = longDate;
    noWeekday.remove(QRegularExpression(QStringLiteral("^dddd[^A-Za-z\\[]*")));
    d->longFormats = {{QStringLiteral("LTS"), lts.isEmpty() ? lt : lts},
                      {QStringLiteral("LT"), lt},
                      {QStringLiteral("L"), date},
                      {QStringLiteral("LL"), noWeekday},
                      {QStringLiteral("LLL"), noWeekday + u' ' + lt},
                      {QStringLiteral("LLLL"), longDate + u' ' + lt}};
    deriveLowercaseFormats(*d);
    return d;
}

std::shared_ptr<const LocaleData> localeData(const QLocale& locale)
{
    static const std::shared_ptr<const LocaleData> english = makeEnglish();
    if (locale.language() == QLocale::English || locale.language() == QLocale::C)
        return english;
    static QMutex mutex;
    static QHash<QString, std::shared_ptr<const LocaleData>> cache;
    const QString key = locale.name();
    QMutexLocker lock(&mutex);
    auto it = cache.constFind(key);
    if (it != cache.cend())
        return *it;
    auto d = makeFromQLocale(locale);
    cache.insert(key, d);
    return d;
}

QString ordinal(qint64 n, const LocaleData& L)
{
    if (!L.english)
        return QString::number(n) + u'.';
    const qint64 b = n % 10;
    const char* suffix = ((n % 100) / 10) == 1 ? "th" : b == 1 ? "st" : b == 2 ? "nd" : b == 3 ? "rd" : "th";
    return QString::number(n) + QLatin1StringView(suffix);
}

QString meridiem(int hour, bool lower, const LocaleData& L)
{
    if (L.english)
        return hour > 11 ? (lower ? QStringLiteral("pm") : QStringLiteral("PM")) : (lower ? QStringLiteral("am") : QStringLiteral("AM"));
    const QString& t = hour > 11 ? L.pm : L.am;
    return lower ? t.toLower() : t;
}

QString expandFormatWith(const QString& format, const LocaleData& L)
{
    QString fmt = format;
    for (int round = 0; round < 6; ++round) { // moment: `i = 5; while (i >= 0 && regex.test(format))`
        bool any = false;
        QString out;
        out.reserve(fmt.size() + 16);
        const QStringView s(fmt);
        qsizetype p = 0;
        while (p < s.size()) {
            if (s[p] == u'[') {
                const qsizetype end = bracketGroupEnd(s, p);
                if (end >= 0) {
                    out += s.mid(p, end - p + 1);
                    p = end + 1;
                    any = true;
                    continue;
                }
            }
            if (s[p] == u'\\') {
                const qsizetype len = localTokenLength(s, p + 1);
                if (len > 0) { // escaped: longDateFormat("\\LT") is undefined -> kept verbatim
                    out += s.mid(p, len + 1);
                    p += len + 1;
                    any = true;
                    continue;
                }
            }
            const qsizetype len = localTokenLength(s, p);
            if (len > 0) {
                const QString key = s.mid(p, len).toString();
                out += L.longFormats.value(key, key);
                p += len;
                any = true;
                continue;
            }
            out += s[p];
            ++p;
        }
        if (!any)
            break;
        fmt = out;
    }
    return fmt;
}

// ---------------------------------------------------------------------------------------------------------
// Formatting

struct Fields {
    qint64 year = 1970; // astronomical
    int month = 1;      // 1..12
    int day = 1;
    int hour = 0;
    int minute = 0;
    int second = 0;
    int ms = 0;
    int weekday = 4; // 0 = Sunday
    int dayOfYear = 1;
    int offsetMinutes = 0;
    qint64 epochMs = 0;
    bool utcMode = false;
};

QString zeroFill(qint64 number, int width, bool forceSign = false)
{
    const QString abs = QString::number(number < 0 ? -number : number);
    QString out;
    if (number >= 0) {
        if (forceSign)
            out += u'+';
    } else {
        out += u'-';
    }
    if (abs.size() < width)
        out += QString(width - abs.size(), u'0');
    out += abs;
    return out;
}

bool monthsInFormat(const QString& format)
{
    static const QRegularExpression re(QStringLiteral("D[oD]?(\\[[^\\[\\]]*\\]|\\s)+MMMM?"));
    return re.match(format).hasMatch();
}

QString formatToken(int id, const QString& tok, const Fields& f, const LocaleData& L, const QString& expandedFormat)
{
    const auto eraYear = [&] { return f.year >= 1 ? f.year : 1 - f.year; };
    switch (id) {
    case kY:
        return f.year <= 9999 ? zeroFill(f.year, 4) : u'+' + QString::number(f.year);
    case kYY:
        return zeroFill(f.year % 100, 2);
    case kYYYY:
        return zeroFill(f.year, 4);
    case kYYYYY:
        return zeroFill(f.year, 5);
    case kYYYYYY:
        return zeroFill(f.year, 6, true);
    case kQ:
        return QString::number((f.month + 2) / 3);
    case kQo:
        return ordinal((f.month + 2) / 3, L);
    case kM:
        return QString::number(f.month);
    case kMo:
        return ordinal(f.month, L);
    case kMM:
        return zeroFill(f.month, 2);
    case kMMM:
        return (L.english || monthsInFormat(expandedFormat) ? L.monthsShort : L.monthsShortStandalone)[f.month - 1];
    case kMMMM:
        return (L.english || monthsInFormat(expandedFormat) ? L.months : L.monthsStandalone)[f.month - 1];
    case kD:
        return QString::number(f.day);
    case kDo:
        return ordinal(f.day, L);
    case kDD:
        return zeroFill(f.day, 2);
    case kDDD:
        return QString::number(f.dayOfYear);
    case kDDDo:
        return ordinal(f.dayOfYear, L);
    case kDDDD:
        return zeroFill(f.dayOfYear, 3);
    case kd:
        return QString::number(f.weekday);
    case kdo:
        return ordinal(f.weekday, L);
    case kdd:
        return L.weekdaysMin[f.weekday];
    case kddd:
        return L.weekdaysShort[f.weekday];
    case kdddd:
        return L.weekdays[f.weekday];
    case ke:
        return QString::number((f.weekday + 7 - L.dow) % 7);
    case kE:
        return QString::number(f.weekday == 0 ? 7 : f.weekday);
    case kw:
    case kwo:
    case kww: {
        const int w = weekOfYear(f.year, f.dayOfYear, L.dow, L.doy).week;
        return id == kw ? QString::number(w) : id == kwo ? ordinal(w, L) : zeroFill(w, 2);
    }
    case kW:
    case kWo:
    case kWW: {
        const int w = weekOfYear(f.year, f.dayOfYear, 1, 4).week;
        return id == kW ? QString::number(w) : id == kWo ? ordinal(w, L) : zeroFill(w, 2);
    }
    case kgg:
    case kgggg:
    case kggggg: {
        const qint64 y = weekOfYear(f.year, f.dayOfYear, L.dow, L.doy).year;
        return id == kgg ? zeroFill(y % 100, 2) : zeroFill(y, id == kgggg ? 4 : 5);
    }
    case kGG:
    case kGGGG:
    case kGGGGG: {
        const qint64 y = weekOfYear(f.year, f.dayOfYear, 1, 4).year;
        return id == kGG ? zeroFill(y % 100, 2) : zeroFill(y, id == kGGGG ? 4 : 5);
    }
    case kH:
        return QString::number(f.hour);
    case kHH:
        return zeroFill(f.hour, 2);
    case kh:
        return QString::number(f.hour % 12 == 0 ? 12 : f.hour % 12);
    case khh:
        return zeroFill(f.hour % 12 == 0 ? 12 : f.hour % 12, 2);
    case kk:
        return QString::number(f.hour == 0 ? 24 : f.hour);
    case kkk:
        return zeroFill(f.hour == 0 ? 24 : f.hour, 2);
    case khmm:
    case khmmss: {
        QString s = QString::number(f.hour % 12 == 0 ? 12 : f.hour % 12) + zeroFill(f.minute, 2);
        return id == khmmss ? s + zeroFill(f.second, 2) : s;
    }
    case kHmm:
    case kHmmss: {
        QString s = QString::number(f.hour) + zeroFill(f.minute, 2);
        return id == kHmmss ? s + zeroFill(f.second, 2) : s;
    }
    case km:
        return QString::number(f.minute);
    case kmm:
        return zeroFill(f.minute, 2);
    case ks:
        return QString::number(f.second);
    case kss:
        return zeroFill(f.second, 2);
    case kS1:
        return QString::number(f.ms / 100);
    case kS2:
        return zeroFill(f.ms / 10, 2);
    case kS3:
    case kS4:
    case kS5:
    case kS6:
    case kS7:
    case kS8:
    case kS9: {
        const int digits = id - kS1 + 1;
        qint64 v = f.ms;
        for (int i = 3; i < digits; ++i)
            v *= 10;
        return zeroFill(v, digits);
    }
    case ka:
    case kA:
        return meridiem(f.hour, id == ka, L);
    case kZ:
    case kZZ: {
        int off = f.offsetMinutes;
        QChar sign = u'+';
        if (off < 0) {
            off = -off;
            sign = u'-';
        }
        return sign + zeroFill(off / 60, 2) + (id == kZ ? QStringLiteral(":") : QString()) + zeroFill(off % 60, 2);
    }
    case kX:
        return QString::number(floorDiv(f.epochMs, 1000));
    case kx:
        return QString::number(f.epochMs);
    case kz:
        return f.utcMode ? QStringLiteral("UTC") : QString();
    case kzz:
        return f.utcMode ? QStringLiteral("Coordinated Universal Time") : QString();
    case kN:
        return f.year >= 1 ? QStringLiteral("AD") : QStringLiteral("BC");
    case kNNNN:
        return f.year >= 1 ? QStringLiteral("Anno Domini") : QStringLiteral("Before Christ");
    case kNNNNN:
        return f.year >= 1 ? QStringLiteral("AD") : QStringLiteral("BC");
    case ky:
        return QString::number(eraYear());
    case kyo:
        return ordinal(eraYear(), L);
    case kyy:
        return zeroFill(eraYear(), 2);
    case kyyy:
        return zeroFill(eraYear(), 3);
    case kyyyy:
        return zeroFill(eraYear(), 4);
    default:
        return tok;
    }
}

Fields fieldsOf(const QDateTime& dt)
{
    Fields f;
    const QDate d = dt.date();
    const QTime t = dt.time();
    f.year = toAstronomicalYear(d.year());
    f.month = d.month();
    f.day = d.day();
    f.hour = t.hour();
    f.minute = t.minute();
    f.second = t.second();
    f.ms = t.msec();
    f.weekday = weekdayOfDays(daysFromCivil(f.year, f.month, f.day));
    f.dayOfYear = dayOfYear(f.year, f.month, f.day);
    f.offsetMinutes = int(std::lround(dt.offsetFromUtc() / 60.0));
    f.epochMs = dt.toMSecsSinceEpoch();
    const Qt::TimeSpec spec = dt.timeSpec();
    f.utcMode = spec == Qt::UTC || spec == Qt::OffsetFromUTC;
    return f;
}

// ---------------------------------------------------------------------------------------------------------
// Strict parsing

enum Field { YEAR = 0, MONTH, DATE, HOUR, MINUTE, SECOND, MILLISECOND };

constexpr qint64 kSaturate = qint64(1) << 52; // |values| beyond this can only produce invalid dates

bool isAsciiDigit(QChar c) { return c >= u'0' && c <= u'9'; }

qsizetype countDigits(QStringView s, qsizetype from, qsizetype max = std::numeric_limits<qsizetype>::max())
{
    qsizetype n = 0;
    while (from + n < s.size() && n < max && isAsciiDigit(s[from + n]))
        ++n;
    return n;
}

// \d{min,max}
qsizetype matchDigits(QStringView s, qsizetype min, qsizetype max)
{
    const qsizetype n = countDigits(s, 0, max);
    return n >= min ? n : 0;
}

// [+-]?\d{min,max} (a leading sign that is not followed by enough digits fails at this position)
qsizetype matchSignedDigits(QStringView s, qsizetype min, qsizetype max)
{
    if (!s.isEmpty() && (s[0] == u'+' || s[0] == u'-')) {
        const qsizetype n = countDigits(s, 1, max);
        return n >= min ? n + 1 : 0;
    }
    return matchDigits(s, min, max);
}

// ^[1-9]\d?
qsizetype matchNoLeadingZero(QStringView s)
{
    if (s.isEmpty() || !isAsciiDigit(s[0]) || s[0] == u'0')
        return 0;
    return s.size() > 1 && isAsciiDigit(s[1]) ? 2 : 1;
}

// ^([1-9]\d|\d)
qsizetype matchHasZero(QStringView s)
{
    if (s.isEmpty() || !isAsciiDigit(s[0]))
        return 0;
    return s[0] != u'0' && s.size() > 1 && isAsciiDigit(s[1]) ? 2 : 1;
}

// [+-]?\d+(\.\d{1,3})?
qsizetype matchTimestamp(QStringView s)
{
    qsizetype n = matchSignedDigits(s, 1, std::numeric_limits<qsizetype>::max());
    if (n == 0)
        return 0;
    if (n < s.size() && s[n] == u'.') {
        const qsizetype frac = countDigits(s, n + 1, 3);
        if (frac > 0)
            n += 1 + frac;
    }
    return n;
}

// Z|[+-]\d\d(?::?\d\d)?   (case-insensitive)
qsizetype matchShortOffset(QStringView s)
{
    if (s.isEmpty())
        return 0;
    if (s[0] == u'Z' || s[0] == u'z')
        return 1;
    if ((s[0] != u'+' && s[0] != u'-') || countDigits(s, 1, 2) != 2)
        return 0;
    if (s.size() > 3 && s[3] == u':' && countDigits(s, 4, 2) == 2)
        return 6;
    if (countDigits(s, 3, 2) == 2)
        return 5;
    return 3;
}

bool isWordClassChar(QChar c) // ['a-z\u00A0-\u05FF\u0700-\uD7FF\uF900-\uFDCF\uFDF0-\uFF07\uFF10-\uFFEF] with /i
{
    const char16_t u = c.unicode();
    return u == u'\'' || (u >= u'a' && u <= u'z') || (u >= u'A' && u <= u'Z') || (u >= 0x00A0 && u <= 0x05FF)
        || (u >= 0x0700 && u <= 0xD7FF) || (u >= 0xF900 && u <= 0xFDCF) || (u >= 0xFDF0 && u <= 0xFF07)
        || (u >= 0xFF10 && u <= 0xFFEF);
}

bool isArabicChar(QChar c) { return c.unicode() >= 0x0600 && c.unicode() <= 0x06FF; }

// moment's matchWord: [0-9]{0,256}[word]{1,256} | [\u0600-\u06FF\/]{1,256}(\s*?[\u0600-\u06FF]{1,256}){1,2}
qsizetype matchWord(QStringView s)
{
    const qsizetype digits = countDigits(s, 0, 256);
    qsizetype letters = 0;
    while (digits + letters < s.size() && letters < 256 && isWordClassChar(s[digits + letters]))
        ++letters;
    if (letters > 0)
        return digits + letters;
    // (digits followed by no letters: fewer digits cannot help since digits are not word chars)
    qsizetype a = 0;
    while (a < s.size() && a < 256 && (isArabicChar(s[a]) || s[a] == u'/'))
        ++a;
    if (a == 0)
        return 0;
    qsizetype end = a;
    for (int group = 0; group < 2; ++group) {
        qsizetype p = end;
        while (p < s.size() && s[p].isSpace())
            ++p;
        qsizetype k = 0;
        while (p + k < s.size() && k < 256 && isArabicChar(s[p + k]))
            ++k;
        if (k == 0)
            break;
        end = p + k;
        if (group == 0 && end == a)
            break;
    }
    return end > a ? end : 0;
}

// Parses the leading run of a numeric string the way JS `+str` / parseInt would, saturated.
qint64 toInt(QStringView s)
{
    bool neg = false;
    qsizetype i = 0;
    if (i < s.size() && (s[i] == u'+' || s[i] == u'-')) {
        neg = s[i] == u'-';
        ++i;
    }
    qint64 v = 0;
    for (; i < s.size() && isAsciiDigit(s[i]); ++i) {
        v = v * 10 + (s[i].unicode() - u'0');
        if (v > kSaturate)
            v = kSaturate;
    }
    return neg ? -v : v;
}

qint64 parseTwoDigitYear(QStringView s)
{
    const qint64 v = toInt(s);
    return v + (v > 68 ? 1900 : 2000);
}

int namesIndex(QStringView input, const std::array<QString, 12>& a, const std::array<QString, 12>& b)
{
    for (int i = 0; i < 12; ++i) {
        for (const QString* names : {&a[i], &b[i]}) {
            QString n = *names;
            const qsizetype dot = n.indexOf(u'.');
            if (dot >= 0)
                n.remove(dot, 1); // moment strips the first '.' of the name before building the regex
            if (input.compare(n, Qt::CaseInsensitive) == 0)
                return i;
        }
    }
    return -1;
}

int weekdayIndex(QStringView input, const std::array<QString, 7>& names)
{
    for (int i = 0; i < 7; ++i) {
        QString n = names[i];
        const qsizetype dot = n.indexOf(u'.');
        if (dot >= 0) { // '.' -> '\.?'
            QString without = n;
            without.remove(dot, 1);
            if (input.compare(without, Qt::CaseInsensitive) == 0)
                return i;
        }
        if (input.compare(n, Qt::CaseInsensitive) == 0)
            return i;
    }
    return -1;
}

struct ParseState {
    std::array<std::optional<qint64>, 7> a;
    std::optional<qint64> dayOfYear;
    bool hasWeek = false;
    std::optional<qint64> wGG, wgg, wW, ww, wE, we, wd;
    QString meridiem;
    bool useUTC = false;
    std::optional<qint64> tzm;
    std::optional<double> epochMs; // X / x set the date directly
    int era = -1;                   // 0 = AD, 1 = BC
    bool bigHour = false;
    bool empty = true;
    bool invalid = false; // invalidMonth / invalidWeekday / invalidEra
};

// Length of the input matched by token `id` at the start of `s` in strict mode (0 = no match). Tokens
// without a parse regex (Mo, Qo, wo, Wo, do, DDDo, z, zz) match their own text, like moment.
qsizetype matchKnownToken(int id, const QString& tok, QStringView s, const LocaleData& L)
{
    switch (id) {
    case kY:
    case kx:
        return matchSignedDigits(s, 1, std::numeric_limits<qsizetype>::max());
    case kYY:
    case kMM:
    case kDD:
    case kww:
    case kWW:
    case kHH:
    case khh:
    case kkk:
    case kmm:
    case kss:
    case kgg:
    case kGG:
    case kS2:
        return matchDigits(s, 2, 2);
    case kYYYY:
    case kgggg:
    case kGGGG:
        return matchDigits(s, 4, 4);
    case kYYYYY:
    case kYYYYYY:
    case kggggg:
    case kGGGGG:
        return matchSignedDigits(s, 6, 6);
    case kM:
    case kD:
    case kw:
    case kW:
    case kh:
    case kk:
        return matchNoLeadingZero(s);
    case kH:
    case km:
    case ks:
        return matchHasZero(s);
    case kd:
    case ke:
    case kE:
        return matchDigits(s, 1, 2);
    case kQ:
    case kS1:
        return matchDigits(s, 1, 1);
    case kS3:
    case kDDDD:
        return matchDigits(s, 3, 3);
    case kDDD:
        return matchDigits(s, 1, 3);
    case kS4:
    case kS5:
    case kS6:
    case kS7:
    case kS8:
    case kS9:
    case ky:
    case kyy:
    case kyyy:
    case kyyyy:
    case kyo:
        return matchDigits(s, 1, std::numeric_limits<qsizetype>::max());
    case khmm:
    case kHmm:
        return matchDigits(s, 3, 4);
    case khmmss:
    case kHmmss:
        return matchDigits(s, 5, 6);
    case kMMM:
    case kMMMM:
    case kdd:
    case kddd:
    case kdddd:
        return matchWord(s);
    case kDo: {
        if (!L.english) { // \d{1,2}\.
            const qsizetype n = countDigits(s, 0, 2);
            return n > 0 && n < s.size() && s[n] == u'.' ? n + 1 : 0;
        }
        for (qsizetype n = countDigits(s, 0, 2); n >= 1; --n) { // \d{1,2}(th|st|nd|rd), backtracking
            const QStringView suf = s.mid(n, 2);
            if (suf == QLatin1StringView("th") || suf == QLatin1StringView("st") || suf == QLatin1StringView("nd")
                || suf == QLatin1StringView("rd"))
                return n + 2;
        }
        return 0;
    }
    case ka:
    case kA: {
        if (!L.english) {
            for (const QString& t : {L.am, L.pm})
                if (!t.isEmpty() && s.startsWith(t, Qt::CaseInsensitive))
                    return t.size();
            return 0;
        }
        if (s.isEmpty() || (s[0].toLower() != u'a' && s[0].toLower() != u'p')) // [ap]\.?m?\.?  /i
            return 0;
        qsizetype n = 1;
        if (n < s.size() && s[n] == u'.')
            ++n;
        if (n < s.size() && s[n].toLower() == u'm')
            ++n;
        if (n < s.size() && s[n] == u'.')
            ++n;
        return n;
    }
    case kZ:
    case kZZ:
        return matchShortOffset(s);
    case kX:
        return matchTimestamp(s);
    case kN:
    case kNNNNN:
        for (QLatin1StringView e : {QLatin1StringView("AD"), QLatin1StringView("BC")})
            if (s.startsWith(e, Qt::CaseInsensitive))
                return 2;
        return 0;
    case kNNNN:
        for (QLatin1StringView e : {QLatin1StringView("Anno Domini"), QLatin1StringView("Before Christ")})
            if (s.startsWith(e, Qt::CaseInsensitive))
                return e.size();
        return 0;
    default: // Mo Qo wo Wo do DDDo z zz: the regex is the token text itself
        return s.startsWith(tok) ? tok.size() : 0;
    }
}

void applyToken(int id, QStringView in, ParseState& st, const LocaleData& L)
{
    auto& a = st.a;
    switch (id) {
    case kY:
    case kYYYYY:
    case kYYYYYY:
    case ky:
    case kyy:
    case kyyy:
    case kyyyy:
    case kyo:
        a[YEAR] = toInt(in);
        break;
    case kYY:
        a[YEAR] = parseTwoDigitYear(in);
        break;
    case kYYYY:
        a[YEAR] = in.size() == 2 ? parseTwoDigitYear(in) : toInt(in);
        break;
    case kM:
    case kMM:
        a[MONTH] = toInt(in) - 1;
        break;
    case kMMM:
    case kMMMM: {
        const int m = id == kMMM ? namesIndex(in, L.monthsShort, L.monthsShortStandalone)
                                 : namesIndex(in, L.months, L.monthsStandalone);
        if (m >= 0)
            a[MONTH] = m;
        else
            st.invalid = true;
        break;
    }
    case kw:
    case kww:
        st.hasWeek = true;
        st.ww = toInt(in);
        break;
    case kW:
    case kWW:
        st.hasWeek = true;
        st.wW = toInt(in);
        break;
    case kd:
        st.hasWeek = true;
        st.wd = toInt(in);
        break;
    case ke:
        st.hasWeek = true;
        st.we = toInt(in);
        break;
    case kE:
        st.hasWeek = true;
        st.wE = toInt(in);
        break;
    case kdd:
    case kddd:
    case kdddd: {
        st.hasWeek = true;
        const int d = weekdayIndex(in, id == kdd ? L.weekdaysMin : id == kddd ? L.weekdaysShort : L.weekdays);
        if (d >= 0)
            st.wd = d;
        else
            st.invalid = true;
        break;
    }
    case kgggg:
    case kggggg:
        st.hasWeek = true;
        st.wgg = toInt(in);
        break;
    case kGGGG:
    case kGGGGG:
        st.hasWeek = true;
        st.wGG = toInt(in);
        break;
    case kgg:
        st.hasWeek = true;
        st.wgg = parseTwoDigitYear(in);
        break;
    case kGG:
        st.hasWeek = true;
        st.wGG = parseTwoDigitYear(in);
        break;
    case kH:
    case kHH:
        a[HOUR] = toInt(in);
        break;
    case kk:
    case kkk: {
        const qint64 k = toInt(in);
        a[HOUR] = k == 24 ? 0 : k;
        break;
    }
    case kh:
    case khh:
        a[HOUR] = toInt(in);
        st.bigHour = true;
        break;
    case khmm:
    case kHmm: {
        const qsizetype pos = in.size() - 2;
        a[HOUR] = toInt(in.left(pos));
        a[MINUTE] = toInt(in.mid(pos));
        if (id == khmm)
            st.bigHour = true;
        break;
    }
    case khmmss:
    case kHmmss: {
        const qsizetype p1 = in.size() - 4, p2 = in.size() - 2;
        a[HOUR] = toInt(in.left(p1));
        a[MINUTE] = toInt(in.mid(p1, 2));
        a[SECOND] = toInt(in.mid(p2));
        if (id == khmmss)
            st.bigHour = true;
        break;
    }
    case ka:
    case kA:
        st.meridiem = in.toString();
        break;
    case km:
    case kmm:
        a[MINUTE] = toInt(in);
        break;
    case ks:
    case kss:
        a[SECOND] = toInt(in);
        break;
    case kS1:
    case kS2:
    case kS3:
    case kS4:
    case kS5:
    case kS6:
    case kS7:
    case kS8:
    case kS9: // toInt(('0.' + input) * 1000), in floating point like JS
        a[MILLISECOND] = qint64(std::floor(QString(QLatin1StringView("0.") + in).toDouble() * 1000));
        break;
    case kD:
    case kDD:
        a[DATE] = toInt(in);
        break;
    case kDo:
        a[DATE] = toInt(in.left(countDigits(in, 0, 2)));
        break;
    case kDDD:
    case kDDDD:
        st.dayOfYear = toInt(in);
        break;
    case kQ:
        a[MONTH] = (toInt(in) - 1) * 3;
        break;
    case kZ:
    case kZZ: {
        st.useUTC = true;
        qint64 minutes = 0;
        bool neg = false;
        if (in.size() >= 3) { // [+-]hh(:?mm)?
            neg = in[0] == u'-';
            minutes = toInt(in.mid(1, 2)) * 60;
            const QStringView rest = in.mid(3);
            const QStringView mm = rest.startsWith(u':') ? rest.mid(1) : rest;
            if (!mm.isEmpty())
                minutes += toInt(mm);
        }
        st.tzm = minutes == 0 ? 0 : (neg ? -minutes : minutes);
        break;
    }
    case kX:
        st.epochMs = std::trunc(in.toString().toDouble() * 1000);
        break;
    case kx:
        st.epochMs = double(toInt(in));
        break;
    case kN:
    case kNNNN:
    case kNNNNN: {
        const QString up = in.toString().toUpper();
        if (up == QLatin1StringView("AD") || up == QLatin1StringView("ANNO DOMINI"))
            st.era = 0;
        else if (up == QLatin1StringView("BC") || up == QLatin1StringView("BEFORE CHRIST"))
            st.era = 1;
        else
            st.invalid = true;
        break;
    }
    default:
        break; // Mo, Qo, wo, Wo, do, DDDo, z, zz: no parse callback
    }
}

std::optional<QDateTime> parseStrictImpl(const QString& text, const QString& format, const QDateTime& nowIn, const LocaleData& L)
{
    if (format.isEmpty()) { // moment(text) without a format: ISO 8601
        QDateTime dt = QDateTime::fromString(text, Qt::ISODateWithMs);
        if (!dt.isValid()) {
            const QDate d = QDate::fromString(text, Qt::ISODate);
            if (d.isValid())
                dt = QDateTime(d, QTime(0, 0));
        }
        return dt.isValid() ? std::optional<QDateTime>(dt) : std::nullopt;
    }

    const QStringList tokens = tokenize(expandFormatWith(format, L));
    ParseState st;
    QStringView rest(text);
    for (const QString& tok : tokens) {
        const int id = tokenId(tok);
        qsizetype len = 0;
        if (id >= 0) {
            len = matchKnownToken(id, tok, rest, L);
        } else if (tok == QLatin1StringView("g") || tok == QLatin1StringView("G")) {
            len = matchSignedDigits(rest, 1, std::numeric_limits<qsizetype>::max()); // regex exists, no token
        } else {
            const QString lit = unescapeFormat(tok);
            len = !lit.isEmpty() && rest.startsWith(lit) ? lit.size() : 0;
        }
        if (len <= 0)
            return std::nullopt; // strict: unused token or skipped input
        const QStringView input = rest.left(len);
        rest = rest.mid(len);
        if (id >= 0) {
            st.empty = false;
            applyToken(id, input, st, L);
        }
    }
    if (!rest.isEmpty() || st.empty || st.invalid)
        return std::nullopt;

    auto& a = st.a;
    if (a[HOUR] && *a[HOUR] <= 12 && *a[HOUR] > 0)
        st.bigHour = false;
    if (st.bigHour)
        return std::nullopt;
    bool parsedParts = false;
    for (const auto& v : a)
        parsedParts = parsedParts || v.has_value();
    if (!st.meridiem.isEmpty()) {
        if (!parsedParts)
            return std::nullopt;
        if (a[HOUR]) { // meridiemFixWrap
            const bool isPm = L.english ? st.meridiem[0].toLower() == u'p' : st.meridiem.compare(L.pm, Qt::CaseInsensitive) == 0;
            if (isPm && *a[HOUR] < 12)
                *a[HOUR] += 12;
            if (!isPm && *a[HOUR] == 12)
                a[HOUR] = 0;
        }
    }
    if (st.era >= 0) // erasConvertYear: AD since year 1, BC since year 0 counting backwards
        a[YEAR] = st.era == 0 ? (a[YEAR] ? *a[YEAR] : 1) : (a[YEAR] ? 1 - *a[YEAR] : 0);

    const QDateTime now = nowIn.isValid() ? nowIn : QDateTime::currentDateTime();
    const QDate today = st.useUTC ? now.toUTC().date() : now.toLocalTime().date();
    const qint64 current[3] = {toAstronomicalYear(today.year()), today.month() - 1, today.day()};

    bool overflowDayOfYear = false, overflowWeeks = false, overflowWeekday = false, weekdayMismatch = false;
    bool nextDay = false;
    if (!st.epochMs) {
        if (st.hasWeek && !a[DATE] && !a[MONTH]) { // dayOfYearFromWeekInfo
            const QDate localToday = now.toLocalTime().date();
            const qint64 ly = toAstronomicalYear(localToday.year());
            const int ldoy = dayOfYear(ly, localToday.month(), localToday.day());
            int dow, doy;
            qint64 weekYear, week, weekday;
            bool weekdayOverflow = false;
            if (st.wGG || st.wW || st.wE) {
                dow = 1;
                doy = 4;
                weekYear = st.wGG ? *st.wGG : a[YEAR] ? *a[YEAR] : weekOfYear(ly, ldoy, 1, 4).year;
                week = st.wW ? *st.wW : 1;
                weekday = st.wE ? *st.wE : 1;
                weekdayOverflow = weekday < 1 || weekday > 7;
            } else {
                dow = L.dow;
                doy = L.doy;
                const WeekOfYear cur = weekOfYear(ly, ldoy, dow, doy);
                weekYear = st.wgg ? *st.wgg : a[YEAR] ? *a[YEAR] : cur.year;
                week = st.ww ? *st.ww : cur.week;
                if (st.wd) {
                    weekday = *st.wd;
                    weekdayOverflow = weekday < 0 || weekday > 6;
                } else if (st.we) {
                    weekday = *st.we + dow;
                    weekdayOverflow = *st.we < 0 || *st.we > 6;
                } else {
                    weekday = dow;
                }
            }
            if (!yearInDateRange(weekYear) || week < 1 || week > weeksInYear(weekYear, dow, doy)) {
                overflowWeeks = true;
            } else if (weekdayOverflow) {
                overflowWeekday = true;
            } else {
                const YearDayOfYear t = dayOfYearFromWeeks(weekYear, week, weekday, dow, doy);
                a[YEAR] = t.year;
                st.dayOfYear = t.dayOfYear;
            }
        }
        if (st.dayOfYear) {
            const qint64 yearToUse = a[YEAR] ? *a[YEAR] : current[0];
            if (!yearInDateRange(yearToUse) || *st.dayOfYear > daysInYear(yearToUse) || *st.dayOfYear == 0)
                overflowDayOfYear = true;
            if (yearInDateRange(yearToUse) && *st.dayOfYear < kSaturate) {
                const Civil c = civilFromDays(daysFromCivil(yearToUse, 1, *st.dayOfYear));
                a[MONTH] = c.m - 1;
                a[DATE] = c.d;
            }
        }
        int i = 0;
        for (; i < 3 && !a[i]; ++i)
            a[i] = current[i];
        for (; i < 7; ++i)
            if (!a[i])
                a[i] = i == DATE ? 1 : 0;
        if (*a[HOUR] == 24 && *a[MINUTE] == 0 && *a[SECOND] == 0 && *a[MILLISECOND] == 0) {
            nextDay = true;
            a[HOUR] = 0;
        }
        if (!yearInDateRange(*a[YEAR]) || std::abs(*a[MONTH]) > kSaturate / 64 || std::abs(*a[DATE]) > kSaturate / 64)
            return std::nullopt;
        if (st.hasWeek && st.wd) { // weekday of the (normalised) date before offsets are applied
            const qint64 y = *a[YEAR] + floorDiv(*a[MONTH], 12);
            const int m = int(floorMod(*a[MONTH], 12)) + 1;
            const int expected = weekdayOfDays(daysFromCivil(y, m, 1) + *a[DATE] - 1);
            weekdayMismatch = *st.wd != expected;
        }
        if (nextDay)
            a[HOUR] = 24;
    } else if (std::isnan(*st.epochMs) || std::abs(*st.epochMs) > double(kMaxEpochMs)) {
        return std::nullopt;
    }

    // checkOverflow (undefined fields compare false, like JS)
    const auto lt = [](const std::optional<qint64>& v, qint64 x) { return v && *v < x; };
    const auto gt = [](const std::optional<qint64>& v, qint64 x) { return v && *v > x; };
    const auto ne0 = [](const std::optional<qint64>& v) { return !v || *v != 0; };
    int overflow = -1;
    if (lt(a[MONTH], 0) || gt(a[MONTH], 11))
        overflow = MONTH;
    else if (lt(a[DATE], 1) || (a[YEAR] && a[MONTH] && gt(a[DATE], daysInMonth(*a[YEAR], *a[MONTH]))))
        overflow = DATE;
    else if (lt(a[HOUR], 0) || gt(a[HOUR], 24) || (a[HOUR] && *a[HOUR] == 24 && (ne0(a[MINUTE]) || ne0(a[SECOND]) || ne0(a[MILLISECOND]))))
        overflow = HOUR;
    else if (lt(a[MINUTE], 0) || gt(a[MINUTE], 59))
        overflow = MINUTE;
    else if (lt(a[SECOND], 0) || gt(a[SECOND], 59))
        overflow = SECOND;
    else if (lt(a[MILLISECOND], 0) || gt(a[MILLISECOND], 999))
        overflow = MILLISECOND;
    if (overflowDayOfYear && (overflow < YEAR || overflow > DATE))
        overflow = DATE;
    if ((overflowWeeks || overflowWeekday) && overflow == -1)
        overflow = 7;
    if (overflow >= 0 || weekdayMismatch)
        return std::nullopt;

    if (st.epochMs)
        return QDateTime::fromMSecsSinceEpoch(qint64(*st.epochMs));

    const int hour = nextDay ? 0 : int(*a[HOUR]);
    const QDate date(toQDateYear(*a[YEAR]), int(*a[MONTH]) + 1, int(*a[DATE]));
    const QTime time(hour, int(*a[MINUTE]), int(*a[SECOND]), int(*a[MILLISECOND]));
    if (!date.isValid() || !time.isValid())
        return std::nullopt;
    QDateTime dt = st.tzm ? QDateTime(date, time, QTimeZone::fromSecondsAheadOfUtc(int(*st.tzm) * 60)) : QDateTime(date, time);
    if (nextDay)
        dt = dt.addDays(1);
    return dt;
}

} // namespace

QString expandMomentFormat(const QString& format, const QLocale& locale)
{
    return expandFormatWith(format, *localeData(locale));
}

QString formatMoment(const QDateTime& dt, const QString& format, const QLocale& locale)
{
    if (!dt.isValid())
        return QStringLiteral("Invalid date");
    const auto L = localeData(locale);
    const QString expanded = expandFormatWith(format, *L);
    const Fields f = fieldsOf(dt);
    QString out;
    out.reserve(expanded.size() * 2);
    for (const QString& tok : tokenize(expanded)) {
        const int id = tokenId(tok);
        out += id >= 0 ? formatToken(id, tok, f, *L, expanded) : removeFormattingTokens(tok);
    }
    return out;
}

std::optional<QDateTime> parseMomentStrict(const QString& text, const QString& format, const QLocale& locale)
{
    return parseStrictImpl(text, format, QDateTime(), *localeData(locale));
}

std::optional<QDateTime> parseMomentStrict(const QString& text, const QString& format, const QDateTime& now, const QLocale& locale)
{
    return parseStrictImpl(text, format, now, *localeData(locale));
}

} // namespace oc
